def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = set()
    stack = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == 8 and (r == 0 or c == 0 or r == h-1 or c == w-1)]
    while stack:
        r, c = stack.pop()
        if (r, c) in outside:
            continue
        outside.add((r, c))
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 8 and (nr,nc) not in outside:
                stack.append((nr,nc))
    return [[7 if grid[r][c] == 8 and (r,c) not in outside else grid[r][c]
             for c in range(w)] for r in range(h)]
